<template><section class="analytics"><div class="metric-picker"><button v-for="metric in metrics" :key="metric.key" type="button" :class="{selected: form.selectedMetric === metric.key}" @click="form.selectedMetric = metric.key">{{ metric.label }}</button></div><div class="chart" aria-label="教学模拟趋势图"><div v-for="(point,index) in points" :key="index" class="bar" :style="{height:`${point}%`}"><span>{{ point }}</span></div></div><div class="ranking"><div v-for="(item,index) in ranking" :key="item.name"><b>{{ index + 1 }}</b><span>{{ item.name }}</span><strong>{{ item.value }}</strong></div></div><label class="analysis-note">分析结论<textarea :value="String(form.analysisNote ?? '')" rows="3" placeholder="记录你对趋势和排行榜的判断" @input="form.analysisNote = ($event.target as HTMLTextAreaElement).value" /></label></section></template>
<script setup lang="ts">const props=defineProps<{modelValue:Record<string,unknown>}>(); const emit=defineEmits<{ 'update:modelValue':[Record<string,unknown>]} >(); const form=computed({get:()=>props.modelValue,set:value=>emit('update:modelValue',value)}); const metrics=[{key:'GMV',label:'成交额'},{key:'VISITORS',label:'访客数'},{key:'ORDERS',label:'订单数'}]; const points=[42,56,48,70,64,82,76]; const ranking=[{name:'校园随行杯',value:'¥2,990'},{name:'开学收纳盒',value:'¥2,360'},{name:'实训帆布袋',value:'¥1,840'}]; watch(form,value=>emit('update:modelValue',{...value}),{deep:true})</script>
<style scoped>.analytics{display:grid;gap:16px}.metric-picker{display:flex;gap:8px;flex-wrap:wrap}.metric-picker button{min-height:34px;padding:0 12px;border:1px solid #d0d5dd;border-radius:6px;background:#fff;color:#475467;cursor:pointer}.metric-picker button.selected{border-color:#1677ff;background:#eff8ff;color:#145bc2}.chart{display:flex;align-items:end;gap:12px;height:170px;padding:18px 18px 0;border:1px solid #eaecf0;border-radius:6px;background:linear-gradient(to top,#f8fafc 1px,transparent 1px);background-size:100% 34px}.bar{position:relative;flex:1;min-width:16px;max-width:44px;border-radius:4px 4px 0 0;background:#4f8cff}.bar span{position:absolute;top:-19px;width:100%;color:#667085;text-align:center;font-size:10px}.ranking{display:grid;gap:8px}.ranking div{display:grid;grid-template-columns:24px 1fr auto;gap:8px;align-items:center;padding:10px 12px;border:1px solid #eaecf0;border-radius:6px;font-size:12px}.ranking b{color:#1677ff}.ranking strong{color:#172033}.analysis-note{display:grid;gap:7px;color:#344054;font-size:13px;font-weight:700}textarea{resize:vertical;padding:10px;border:1px solid #d0d5dd;border-radius:6px;font:inherit;font-weight:400}
</style>
